   if q['beat']==1:ax.axvline(x-.5,color='.5',lw=.8);ax.text(x+1.5,1.01,f"M{q['measure']} · {clock(q['PLP_time_s'])}",ha='center',va='bottom',fontsize=8,transform=ax.get_xaxis_transform())
