  ax.set_ylim(-limit,limit);ax.set_ylabel('Bass − PLP (ms)',fontsize=8);ax.set_xlim(qq[0]['quarter_index']-qbase-.6,qq[-1]['quarter_index']-qbase+.7);ax.set_xticks([q['quarter_index']-qbase for q in qq],[str(q['beat']) for q in qq]);ctx.set_ylim(-.6,.6);ctx.set_yticks([]);ctx.tick_params(bottom=False,labelbottom=False);ctx.spines[['left','right','top','bottom']].set_visible(False);ctx.set_ylabel('ABSTAIN',fontsize=6,rotation=0,labelpad=25)
  for q in qq:
   es=[e for e in unresolved if e['display_context']['nearest_PLP_quarter']==q['quarter']]
