 fig.suptitle('Exactly Like You · M33–M48 · JGA-estimated Bass attacks\n17 unique selections / 63 episodes · median −1.72 ms · 17/64 quarters covered\n0 ms = unchanged RAW PLP · hollow circles = selected attacks · abstention lane = BP context only',fontsize=12)
 return fig
